use CetechDeliveryEngine\Infrastructure\Persistence\{CustomerPolicyCurrentConnection as Connection,CustomerPolicyCurrentSource as Source,InMemoryScopedConfigurationRepository,PolicyAssignmentStore};
use CetechDeliveryEngine\Infrastructure\WordPress\{OperationConnectionMysqliTransport,OperationConnectionResult};
use CetechDeliveryEngine\Tests\Support\CustomerPolicy\CustomerPolicyProofTransport;
use CetechDeliveryEngine\Tests\Support\RuleLifecycle\{RuleProofDatabase as DB,RuleProofFactory};
use CetechDeliveryEngine\Tests\Support\Operation\OperationProofDatabase;
use CetechDeliveryEngine\Tests\Support\PolicyAssignment\PolicyAssignmentProofEnvelope as E;
use CetechDeliveryEngine\Tests\Support\ReturnPolicy\ReturnPolicyProofEnvelope as R;
use CetechDeliveryEngine\Tests\Support\RefundPolicy\RefundPolicyProofEnvelope as F;
use PHPUnit\Framework\Attributes\Group;
use PHPUnit\Framework\TestCase;
/** Real readonly source planning/coherence/budget/retirement, separate from native shopper HTTP grants. */
#[Group('rule-lifecycle-real-db')]
final class CustomerPolicyCurrentRealDatabaseTest extends TestCase {
 private \mysqli$db;private string$prefix;private array$transports=[];private array$factories=[];private string$option_name;
 protected function setUp():void{$this->db=DB::connect();$this->prefix=DB::prefix();DB::install($this->db,$this->prefix);OperationProofDatabase::option($this->db,$this->prefix,SchemaVersion::OPTION_NAME,'12');OperationProofDatabase::option($this->db,$this->prefix,MigrationStatus::OPTION_NAME,serialize(['status'=>'success','to_version'=>'12','migration_id'=>'owned-r24-schema12']));$this->publish(E::RETURN,1,101);$this->publish(E::REFUND,2,201);$this->assign();$this->option_name=E::store($this->prefix)->name(PolicyAssignmentState::make_coordinate(1,'global',0));}
 protected function tearDown():void{foreach($this->transports as$t)$t->force_close();foreach($this->factories as$f)$f->close_all();if(isset($this->db,$this->prefix)){DB::cleanup($this->db,$this->prefix);$this->db->close();}}
 private function factory():RuleProofFactory{$f=new RuleProofFactory($this->prefix,clock:RuleTime::parse(E::NOW));$this->factories[]=$f;return$f;}
 private function publish(string$family,int$logical,int$version,array$content=[]):void{[$return,$refund]=E::families();$f=$this->factory();$class=E::RETURN===$family?R::class:F::class;$service=E::RETURN===$family?new ReturnPolicyCatalogService($return,$f,static fn():bool=>true):new RefundPolicyCatalogService($refund,$f,static fn():bool=>true);$p=$class::create($logical,$version,$content);self::assertSame('accepted',$service->attempt($class::identity($p,'rule.draft.create','r24-create-'.$family.'-'.$version),$p,RequestContext::create())->outcome->state);$opened=$class::opened($this->db,$this->prefix,$logical,$version);self::assertSame('accepted',$service->attempt($class::identity($opened,'rule.publish','r24-publish-'.$family.'-'.$version),$opened,RequestContext::create())->outcome->state);}
 private function assign():void{$c=PolicyAssignmentState::make_coordinate(1,'global',0);$opened=PolicyAssignmentState::absent(1,'global',0);$p=E::payload($opened,0,E::slots('assigned','assigned'),[E::RETURN=>E::witness($this->db,$this->prefix,E::RETURN,E::uuid(1)),E::REFUND=>E::witness($this->db,$this->prefix,E::REFUND,E::uuid(2))]);$id=E::identity($c);self::assertSame('accepted',E::service($this->factory(),$this->prefix,$id)->attempt($id,$p,RequestContext::create())->outcome->state);}
 private function transport():CustomerPolicyProofTransport{$native=OperationConnectionMysqliTransport::connect((string)(getenv('CETECH_DE_REAL_DB_HOST')?:'127.0.0.1'),(string)(getenv('CETECH_DE_REAL_DB_USER')?:'root'),(string)(getenv('CETECH_DE_REAL_DB_PASSWORD')?:''),(string)getenv('CETECH_DE_REAL_DB_NAME'),(int)(getenv('CETECH_DE_REAL_DB_PORT')?:3306));$time=RuleTime::parse(E::NOW)->epoch_microseconds();$value=intdiv($time,1000000).'.'.str_pad((string)($time%1000000),6,'0',STR_PAD_LEFT);self::assertTrue($native->execute('SET timestamp='.$value)->acknowledged);$t=new CustomerPolicyProofTransport($native);$this->transports[]=$t;return$t;}
 private function owner(?callable$configure=null):Connection{$t=$this->transport();if(null!==$configure)$configure($t);return new Connection(1,$this->prefix,$t,'utf8mb4','utf8mb4_unicode_ci');}
 private function source(?callable$configure=null):Source{return new Source(new EffectiveConfigurationResolver(new InMemoryScopedConfigurationRepository(),new EffectiveConfigurationValidator()),fn(array$b)=>$this->owner($configure));}
 private function grant(int$product=33):CustomerPolicyReadGrant{return CustomerPolicyReadGrant::captured(['site_id'=>1,'actor_id'=>0,'session_subject'=>str_repeat('a',64),'product_id'=>$product,'variation_id'=>0,'parent_id'=>0,'quantity'=>'1','real_offer_id'=>20,'context_digest'=>str_repeat('b',64),'cart_key'=>'native-'.$product,'purpose'=>'cart'],['site_id'=>1,'prefix'=>$this->prefix],static fn():bool=>true);}
 private function capture(?callable$configure=null):array{return(new CustomerPolicyCurrentProvider($this->source($configure)))->capture_batch(['line'=>$this->grant()]);}
 private function refusal(callable$fn):void{$failed=false;try{$fn();}catch(\RuntimeException){$failed=true;}self::assertTrue($failed,'Incomplete source observation escaped.');}
 private function final_replies():array{$t=end($this->transports);return array_values(array_filter($t->replies,static fn(array$r):bool=>str_starts_with($r['sql'],'WITH cp_o AS')));}
 public function test_dedicated_owner_is_actually_read_committed_read_only_and_cannot_write_or_commit():void{$c=$this->owner();self::assertTrue($c->begin());$settings=$c->get_row('SELECT @@session.tx_isolation AS isolation_level,@@session.tx_read_only AS read_only');self::assertSame('READ-COMMITTED',$settings['isolation_level']);self::assertSame('1',(string)$settings['read_only']);self::assertFalse($c->query("INSERT INTO `{$this->prefix}options` (option_name,option_value) VALUES ('forbidden','x')"));self::assertSame(OperationCommitResult::NotSent,$c->commit());$native=end($this->transports)->native->execute("INSERT INTO `{$this->prefix}options` (option_name,option_value) VALUES ('server-denies-read-only','x')");self::assertFalse($native->acknowledged);self::assertTrue($c->rollback());self::assertTrue($c->retire());self::assertSame('0',(string)DB::scalar($this->db,"SELECT COUNT(*) FROM `{$this->prefix}options` WHERE option_name='server-denies-read-only'"));}
 public function test_final_single_statement_captures_complete_unicode_sources_and_sql_time_without_writes():void{$before=$this->db->query("CHECKSUM TABLE `{$this->prefix}options` EXTENDED")->fetch_assoc()['Checksum'];$capture=$this->capture();self::assertSame(E::NOW,$capture['line']->captured_at()->sql());self::assertSame('assigned',$capture['line']->families()[E::RETURN]->facts()['disposition']);self::assertStringContainsString('café',$capture['line']->families()[E::RETURN]->private_json());self::assertCount(1,$this->final_replies());self::assertTrue(end($this->transports)->closed);self::assertSame($before,$this->db->query("CHECKSUM TABLE `{$this->prefix}options` EXTENDED")->fetch_assoc()['Checksum']);}
 public function test_assignment_bytes_changed_between_plan_and_final_refuse_without_stale_snapshot():void{$changed=false;$this->refusal(function()use(&$changed){return$this->capture(function(CustomerPolicyProofTransport$t)use(&$changed){$t->before=function(string$sql)use(&$changed){if(!$changed&&str_starts_with($sql,'WITH cp_o AS')){$changed=true;DB::execute($this->db,"UPDATE `{$this->prefix}options` SET option_value=CONCAT(option_value,' ') WHERE option_name='".$this->db->real_escape_string($this->option_name)."'");}};});});self::assertTrue($changed);self::assertTrue(end($this->transports)->closed);}
 public function test_previously_absent_product_scope_created_before_final_is_not_silently_omitted():void{$name=E::store($this->prefix)->name(PolicyAssignmentState::make_coordinate(1,'product',33));$this->refusal(fn()=>$this->capture(function(CustomerPolicyProofTransport$t)use($name){$done=false;$t->before=function(string$sql)use(&$done,$name){if(!$done&&str_starts_with($sql,'WITH cp_o AS')){$done=true;OperationProofDatabase::option($this->db,$this->prefix,$name,'unknown new source');}};}));self::assertSame('1',(string)DB::scalar($this->db,"SELECT COUNT(*) FROM `{$this->prefix}options` WHERE option_name='".$this->db->real_escape_string($name)."'"));}
 public function test_complete_logical_plan_must_still_equal_the_final_current_head_row():void{$this->refusal(fn()=>$this->capture(function(CustomerPolicyProofTransport$t){$done=false;$t->before=function(string$sql)use(&$done){if(!$done&&str_starts_with($sql,'WITH cp_o AS')){$done=true;DB::execute($this->db,"UPDATE `{$this->prefix}delivery_engine_logical_rules` SET revision=revision+1 WHERE logical_uuid='".E::uuid(1)."'");}};}));self::assertCount(1,$this->final_replies());}
 public function test_oversized_logical_scope_is_clipped_inside_the_planning_statement():void{DB::execute($this->db,"UPDATE `{$this->prefix}delivery_engine_logical_rules` SET scope_json='".str_repeat('x',4097)."' WHERE logical_uuid='".E::uuid(1)."'");$this->refusal(fn()=>$this->capture());self::assertSame([],$this->final_replies());$logical=array_values(array_filter(end($this->transports)->replies,static fn(array$r):bool=>str_contains($r['sql'],'CASE WHEN OCTET_LENGTH(`scope_json`)')&&!str_starts_with($r['sql'],'WITH')));self::assertNotEmpty($logical);self::assertNull(end($logical)['result']->rows[0]['scope_json']);}
 public function test_oversized_migration_marker_is_clipped_before_unserialize_or_final_capture():void{OperationProofDatabase::option($this->db,$this->prefix,MigrationStatus::OPTION_NAME,str_repeat('x',16385));$this->refusal(fn()=>$this->capture());self::assertSame([],$this->final_replies());$rows=array_values(array_filter(end($this->transports)->replies,static fn(array$r):bool=>str_starts_with($r['sql'],'SELECT option_id,option_name,CASE')));self::assertNotEmpty($rows);$marker=array_values(array_filter($rows[0]['result']->rows,static fn(array$r):bool=>$r['option_name']===MigrationStatus::OPTION_NAME));self::assertNull($marker[0]['option_value']);}
 public function test_aggregate_option_plan_over_two_mib_suppresses_private_rows_in_sql():void{$grants=[];for($i=1;$i<=150;++$i){$id=100+$i;$grants['line-'.$i]=$this->grant($id);OperationProofDatabase::option($this->db,$this->prefix,E::store($this->prefix)->name(PolicyAssignmentState::make_coordinate(1,'product',$id)),str_repeat('x',16384));}$this->refusal(fn()=>$this->source()->capture_batch($grants));$rows=array_values(array_filter(end($this->transports)->replies,static fn(array$r):bool=>str_starts_with($r['sql'],'SELECT option_id,option_name,CASE')));self::assertNotEmpty($rows);self::assertTrue(count($rows[0]['result']->rows)>100);self::assertSame([],array_filter($rows[0]['result']->rows,static fn(array$r):bool=>null!==$r['option_value']));}
 public function test_final_aggregate_payload_overflow_transports_only_a_null_budget_clock_row():void{$this->refusal(fn()=>$this->capture(function(CustomerPolicyProofTransport$t){$done=false;$t->before=function(string$sql)use(&$done){if(!$done&&str_starts_with($sql,'WITH cp_o AS')){$done=true;DB::execute($this->db,"UPDATE `{$this->prefix}delivery_engine_rule_versions` SET payload_json='".str_repeat('x',2097153)."' WHERE version_uuid='".E::uuid(101)."'");}};}));$replies=$this->final_replies();self::assertCount(1,$replies);self::assertCount(1,$replies[0]['result']->rows);self::assertSame('clock',$replies[0]['result']->rows[0]['row_tag']);self::assertSame('0',(string)$replies[0]['result']->rows[0]['budget_ok']);self::assertNull($replies[0]['result']->rows[0]['payload_json']);}
 public function test_history_head_above_one_thousand_refuses_without_fetching_final_payloads():void{DB::execute($this->db,"UPDATE `{$this->prefix}delivery_engine_logical_rules` SET last_version_sequence=1001 WHERE logical_uuid='".E::uuid(1)."'");$this->refusal(fn()=>$this->capture());self::assertSame([],$this->final_replies());}
 public function test_unassigned_capture_does_not_read_private_unselected_catalog_payloads():void{DB::execute($this->db,"DELETE FROM `{$this->prefix}options` WHERE option_name='".$this->db->real_escape_string($this->option_name)."'");$capture=$this->capture();self::assertSame('not_assigned',$capture['line']->families()[E::RETURN]->facts()['disposition']);$reply=$this->final_replies()[0]['result'];self::assertSame([],array_filter($reply->rows,static fn(array$r):bool=>'versions'===$r['row_tag']));}
 public function test_participant_mdl_blocks_exact_ddl_until_read_owner_retires():void{$other=DB::connect();try{$other->query('SET SESSION lock_wait_timeout=1');$held=false;$this->capture(function(CustomerPolicyProofTransport$t)use($other,&$held){$t->before=function(string$sql)use($other,&$held){if(!$held&&str_starts_with($sql,'WITH cp_o AS')){$held=true;self::assertFalse($other->query("ALTER TABLE `{$this->prefix}delivery_engine_rule_versions` COMMENT='owned-read-mdl'"));self::assertSame(1205,$other->errno);}};});self::assertTrue($held);self::assertTrue($other->query("ALTER TABLE `{$this->prefix}delivery_engine_rule_versions` COMMENT='owned-after-retirement'"));}finally{$other->close();}}
 public function test_lost_final_read_reply_never_publishes_private_source_and_retires():void{$this->refusal(fn()=>$this->capture(static function(CustomerPolicyProofTransport$t){$t->after=static fn(string$sql,OperationConnectionResult$r)=>str_starts_with($sql,'WITH cp_o AS')?new OperationConnectionResult(false,true):$r;}));self::assertTrue(end($this->transports)->closed);self::assertCount(1,$this->final_replies());}
 public function test_retirement_failure_after_valid_read_never_publishes_capture():void{$this->refusal(fn()=>$this->capture(static function(CustomerPolicyProofTransport$t){$t->fail_retire=true;}));self::assertCount(1,$this->final_replies());self::assertTrue(end($this->transports)->closed);}
}
